const ROLES=['Product design','UX research','Brand design','Product Management','Product Marketing Management','Growth Marketing','Digital Marketing','Content Strategy','Marketing Analytics','Data Analytics','Business Analytics','Software Engineering','Data Science','UX Writing','Program Management','Project Management','Customer Success','Sales Operations','Business Operations','Strategy & Consulting','Finance','Human Resources','Supply Chain Management','Video Production'];
