const SOURCE_CHECK_DATE='Oct 19, 2026';
function catalogJobs(){return jobs.filter(j=>state.catalog==='demo'?j.demo:!j.demo)}
function passesPay(j){return Number(state.prefs.min||0)===0||(Number.isFinite(j.salaryNum)&&j.salaryNum>=Number(state.prefs.min))}
function normalized(t){return String(t||'').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,' ').trim()}
const keywordAliases={'Customer research':['user research','ux research','customer discovery'],'Product thinking':['product strategy','product thinking'],'Prototyping':['prototypes','prototype','prototyping'],'Product design':['ux design','product design','ui design'],'AI tools':['artificial intelligence','chatgpt','claude','ai tools'],'Market research':['competitive research','competitor research','market research'],'Product positioning':['positioning','product messaging'],'Go-to-market':['gtm','go to market'],'Product roadmap':['roadmapping','roadmap','product roadmap'],'Communication':['communication','communicating','presentations'],'Collaboration':['collaborating','collaboration','teamwork'],'Programming':['programming','python','java','javascript','c plus plus'],'Sports knowledge':['sports','sports knowledge']};
function atsFor(j,text=state.profile.skillsText){const hay=' '+normalized(text)+' ';const keys=j.keywords||[...j.skills,...j.miss];const matched=[],missing=[];keys.forEach(k=>{const terms=[k,...(keywordAliases[k]||[])];(terms.some(t=>hay.includes(' '+normalized(t)+' '))?matched:missing).push(k)});return {matched,missing,total:keys.length,percent:keys.length?Math.round(matched.length/keys.length*100):0}}
function matchTags(j){const a=atsFor(j);return `${a.matched.map(x=>`<span class="skill">✓ ${esc(x)}</span>`).join('')}${a.missing.map(x=>`<span class="skill miss">− ${esc(x)}</span>`).join('')}`}
function originalLink(j,label='Original posting',cls='source-link'){return j.url?`<a class="${cls}" href="${esc(j.url)}" target="_blank" rel="noopener noreferrer">${ico('arrow')} ${label}</a>`:''}
function eligibilityError(j){if(j.noSponsorship&&state.prefs.sponsor==='Yes')return 'This posting explicitly does not offer sponsorship. Change the sponsorship preference only if it accurately reflects your situation, or choose another role.';if(j.noStudentVisa&&state.prefs.auth==='Student / temporary work authorization')return 'This posting excludes temporary or student-based work authorization. Check the employer’s original eligibility requirements and choose an eligible role.';return ''}
function sourceMeta(j){return j.demo?'<span class="badge orange">Workflow sample · not a verified opening</span>':`<span class="badge">${ico('check')} Source checked · ${SOURCE_CHECK_DATE}</span><span class="source-system">${esc(j.ats)}</span>`}
function jobActions(j){const p=state.pairs[j.id];return `${p&&p.status!=='expired'?btn(activePair(p)?`${ico('match')} View match`:`${ico('check')} ${j.demo?statusLabel(p.status):'Interest saved'}`,`pair:${j.id}`,activePair(p)?'primary':''):btn('Not for me',`dismiss:${j.id}`)+btn(`${ico('heart')} I'm interested`,`interest:${j.id}`,'primary')}`}
function atsPanel(id){const j=jobBy(id),a=atsFor(j);overlay(`${head('ATS keyword alignment')}<div class="job-top"><div class="company-logo ${j.id}">${esc(j.logo)}</div><div><h3>${esc(j.title)}</h3><p>${esc(j.company)} · ${j.demo?'Workflow sample':esc(j.ats)}</p></div></div><div class="ats-summary"><div class="ats-number">${a.percent}<small>%</small></div><div><strong>${a.matched.length} of ${a.total} keywords found</strong><p>Transparent keyword coverage from your profile text.</p></div></div><div class="coverage-track"><span style="width:${a.percent}%"></span></div><h4>FOUND IN YOUR PROFILE</h4><div class="skills">${a.matched.length?a.matched.map(x=>`<span class="skill">✓ ${esc(x)}</span>`).join(''):'<p>Add your skills below to see alignment.</p>'}</div><h4>NOT FOUND YET</h4><div class="skills">${a.missing.length?a.missing.map(x=>`<span class="skill miss">− ${esc(x)}</span>`).join(''):'<p>All selected keywords were found.</p>'}</div><form id="ats-form" data-id="${j.id}" novalidate><div class="field"><label for="ats-text">Your skills or resume excerpts</label><textarea id="ats-text" name="skillsText" maxlength="12000" rows="7">${esc(state.profile.skillsText||'')}</textarea><small>Local text matching with common synonyms. Only include skills you have. Uploaded resumes and LinkedIn URLs are not read.</small></div><div id="form-error" class="error" role="alert"></div><div class="panel-footer">${btn('Back to role',`job:${id}`)}<button class="btn primary">Update keyword match</button></div></form><div class="match-explain"><strong>What this score means</strong><br>Keyword coverage = matched terms ÷ selected posting terms. Overall fit also includes role and preferences. Neither score comes from the employer’s ATS or predicts application success.</div>${originalLink(j,'Compare with the original posting')}`)}
function sourcesPanel(){const sources=[['Employer postings','Primary pages with job details and an apply entry point. Ten openings were checked on October 19, 2026; posting dates are not disclosed unless noted.','https://jobs.lever.co/theathletic','Primary source'],['Greenhouse','Direct job pages used for Databricks, Mirakl, and Astera Labs. No ATS API is connected.','https://job-boards.greenhouse.io/mirakl/jobs/6212932004','Source checked'],['Lever','Direct employer postings used for The Athletic, Viget, and Palantir.','https://jobs.lever.co/viget/969d8237-ec1a-4ec4-ba09-b08bcfcd81c4','Source checked'],['Summer 2027 GitHub list','Used to discover job links. Older entries are not treated as evidence that a vacancy is still open.','https://github.com/sndsh404/summer-2027-internships','Discovery'],['Extern PM internship guide','Used for timeline context and cross-checking. Its October 9 update reports that Salesforce’s summer APM posting came down.','https://www.extern.com/post/product-management-internships-summer-2027-guide','Editorial guide'],['APM List','Includes open, upcoming, and not-yet-open programs. Employer pages take precedence over aggregator status.','https://apmlist.org/list/Associate-Product-Manager-Intern','Discovery'],['CMU Handshake','A public listing could not be read from this link. No Handshake vacancy is included as verified.','https://cmu.joinhandshake.com/explore','Not verified'],['Salesforce / Workday','The supplied URL opens an account login, not a vacancy. The older APM link could not be verified and is excluded.','https://salesforce.wd12.myworkdayjobs.com/en-US/External_Career_Site/login?redirect=%2Fen-US%2FExternal_Career_Site%2FuserHome','Not verified'],['LinkedIn','Useful for discovery. No LinkedIn listing is imported or marked source-checked without an employer posting.','https://www.linkedin.com/jobs/','Discovery only']];overlay(`${head('Know where your shortlist comes from.')}<div class="banner">${ico('shield')}<div><strong>Source check: ${SOURCE_CHECK_DATE}</strong><p>This is a curated snapshot. Employer pages were readable with an apply option at review; availability can change. Open the original before applying.</p></div></div>${sources.map(([n,d,url,t])=>`<div class="source-review"><div class="section-head"><h3>${n}</h3><span class="badge gray">${t}</span></div><p>${d}</p><a href="${esc(url)}" target="_blank" rel="noopener noreferrer" class="source-link">Visit source ↗</a></div>`).join('')}<div class="match-explain">No live ATS feed, scraping service, or background refresh is connected. Sample roles are in the Workflow demo tab and never labeled as source-checked openings.</div>`)}

const defaults=()=>({mode:'candidate',page:'shortlist',catalog:'verified',profile:{name:'Celeste Shih',email:'celeste.shih@example.com',headline:'Aspiring product designer',skillsText:DEFAULT_SKILLS,school:'University of California, Berkeley',experience:'0–1 years',source:'linkedin',linkedin:'https://www.linkedin.com/in/celeste-shih-demo',resume:'',terms:true,complete:true},prefs:{role:'Product design',location:'San Francisco, CA',industry:'Technology',jobType:'Any',work:'Any',auth:'Authorized to work in the US',sponsor:'No',min:0},open:true,pairs:{},dismissed:[],saved:[],recruiter:{verified:false,email:'',company:'Linear',claims:[],passed:[],invites:[],day:new Date().toLocaleDateString('en-CA')},searches:0});
let state;try{state=JSON.parse(localStorage.getItem('shortlist-v1'))||defaults()}catch{state=defaults()}
// Preserve existing decisions while upgrading only the original sample identity.
if(state.profile.name==='Alex Morgan')state.profile.name='Celeste Shih';
if(state.profile.email==='alex.morgan@example.com')state.profile.email='celeste.shih@example.com';
if(state.profile.linkedin==='https://www.linkedin.com/in/alex-morgan-demo')state.profile.linkedin='https://www.linkedin.com/in/celeste-shih-demo';
state.profile.skillsText??=DEFAULT_SKILLS;state.prefs.jobType??='Any';state.catalog??='verified';
let filter='all',query='',sort='score',onboarding=null,profileDraft=null,prefsDraft=null,recruiterStep=1,recruiterDraft='',claimDraft=[],toastTimer;
function save(){try{localStorage.setItem('shortlist-v1',JSON.stringify(state))}catch{toast('Browser storage is unavailable. Changes will last for this session.')}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function closeOverlay(){$('#overlay').innerHTML='';document.body.style.overflow='';onboarding=null}function overlay(html,modal=false){$('#overlay').innerHTML=`<div class="${modal?'modal-wrap':'panel-backdrop'}"><section role="dialog" aria-modal="true" aria-labelledby="dialog-title" class="${modal?'modal':'panel'}">${html}</section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>$('#overlay').querySelector('button,input,select')?.focus())}
function head(t){return `<div class="panel-header"><h2 id="dialog-title">${t}</h2><button class="icon-btn" aria-label="Close dialog" data-action="close">${ico('x')}</button></div>`}
function btn(t,a,c=''){return `<button class="btn ${c}" data-action="${a}">${t}</button>`}
const jobBy=id=>jobs.find(j=>j.id===id);const activePair=p=>p&&['mutual','interviewing','offer'].includes(p.status);const count=s=>Object.values(state.pairs).filter(p=>s.includes(p.status)).length;
function render(){const recruiter=state.mode==='recruiter';const pageName={shortlist:recruiter?'Ranked candidates':'Daily shortlist',activity:'My activity',matches:'Mutual matches',profile:'My profile',preferences:'Preferences'}[state.page]||'Daily shortlist';$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="logo"><span class="logo-mark"><i></i><i></i><i></i><i></i></span><span class="logo-word">SHORTLIST</span></div><div class="workspace">YOUR WORKSPACE</div><nav>${nav('shortlist',recruiter?'Ranked candidates':'Daily shortlist','grid')}${nav('activity','My activity','heart')}${nav('matches','Mutual matches','match',count(['mutual','interviewing']))}${nav('profile','My profile','user')}${!recruiter?nav('preferences','Preferences','settings'):''}</nav><div class="side-footer"><div class="sidebar-note">${ico('match')}<strong style="display:block;margin-top:9px">Good things take a good fit.</strong><p class="tiny">Your next opportunity is closer than you think.</p><button class="text-btn" style="color:#c9dda8;font-size:10px" data-action="guide">How SHORTLIST works ${ico('arrow')}</button></div><button class="side-profile" data-action="nav:profile"><div class="avatar">${recruiter?'MC':esc(initials(state.profile.name))}</div><div>${recruiter?'Maya Chen':esc(state.profile.name||'Your profile')}<small>${recruiter?'Recruiter workspace':'Candidate workspace'}</small></div></button></div></aside><div class="content"><header class="topbar"><div class="crumb"><span class="crumb-home">Workspace</span><span class="crumb-home">/</span><strong>${pageName}</strong></div><div class="top-right"><span class="demo-label">UI PROTOTYPE</span><div class="mode-switch" aria-label="Workspace"><button class="${!recruiter?'active':''}" data-action="mode:candidate">Candidate</button><button class="${recruiter?'active':''}" data-action="mode:recruiter">Recruiter</button></div><button class="icon-btn" data-action="notifications" aria-label="Notifications">${ico('bell')}</button></div></header><main class="main">${state.page==='shortlist'?(recruiter?recruiterPage():shortlistPage()):state.page==='activity'?activityPage():state.page==='matches'?matchesPage():state.page==='profile'?profilePage():preferencesPage()}</main></div></div>`;save()}
function nav(page,label,icon,n){return `<button class="nav ${state.page===page?'active':''}" data-action="nav:${page}">${ico(icon)}<span>${label}</span>${n?`<b class="count">${n}</b>`:''}</button>`}
function initials(n){return n?n.split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase():'CS'}
function pageTitle(title,sub,action=''){return `<div class="greeting"><div><div class="eyebrow">A LITTLE CLARITY. A LOT OF POSSIBILITY.</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`}
function shortStats(){return `<div class="stats"><div class="stat"><div class="stat-icon">${ico('briefcase')}</div><div><strong>${catalogJobs().filter(j=>!state.dismissed.includes(j.id)&&passesPay(j)&&(state.prefs.jobType==='Any'||j.jobType===state.prefs.jobType)).length.toString().padStart(2,'0')}</strong><span>${state.catalog==='demo'?'Practice opportunities':'Source-checked opportunities'}</span></div></div><div class="stat"><div class="stat-icon">${ico('heart')}</div><div><strong>${count(['interested','mutual','interviewing','offer']).toString().padStart(2,'0')}</strong><span>Roles you’re interested in</span></div></div><div class="stat"><div class="stat-icon">${ico('match')}</div><div><strong>${count(['mutual','interviewing']).toString().padStart(2,'0')}</strong><span>Mutual matches · demo</span></div></div></div>`}

function shortlistPage(){let list=catalogJobs().filter(j=>!state.dismissed.includes(j.id)&&passesPay(j)&&(state.prefs.jobType==='Any'||j.jobType===state.prefs.jobType));if(filter==='saved')list=list.filter(j=>state.saved.includes(j.id));if(filter==='remote')list=list.filter(j=>j.type==='Remote');if(filter==='intern')list=list.filter(j=>j.jobType==='Internship');if(filter==='full-time')list=list.filter(j=>j.jobType==='Full-time');if(filter==='part-time')list=list.filter(j=>j.jobType==='Part-time');if(filter==='90')list=list.filter(j=>scoreFor(j)>=90);if(query)list=applySearch(list,query);list.sort((a,b)=>scoreFor(b)-scoreFor(a));const demo=state.catalog==='demo';return `${pageTitle(`Good morning, ${esc((state.profile.name||'there').split(' ')[0])}.`,'A few great fits. A fresh start. Your next chapter is here.',`<button class="visibility" data-action="visibility" role="switch" aria-checked="${state.open}"><span class="toggle ${state.open?'on':''}"></span>Open to work ${ico('down')}</button>`)}<section class="hero"><div><div class="eyebrow">LESS SCROLLING. MORE POSSIBILITY.</div><h2>Your next move,<br>a little more intentional.</h2><p>Explore openings with clear sources and context.</p></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="float-card"><b></b><span></span><span style="width:85px"></span><span style="width:45px"></span></div><div class="float-score">${Math.max(0,...catalogJobs().map(scoreFor))}<span style="font-size:11px">%</span></div><span class="spark">✧</span><i class="dot-art"></i></div></section>${shortStats()}<div class="catalog-bar"><div class="catalog-tabs" role="group" aria-label="Job catalog"><button class="${!demo?'active':''}" data-action="catalog:verified">Source-checked openings <span>10</span></button><button class="${demo?'active':''}" data-action="catalog:demo">Workflow demo <span>6</span></button></div><button class="text-btn" data-action="sources">Sources & freshness ↗</button></div><div class="snapshot-note">${ico(demo?'briefcase':'shield')}<p>${demo?'Simulated postings for practicing the two-sided match flow. These are not verified vacancies.':`Employer sources checked ${SOURCE_CHECK_DATE}. A curated snapshot; availability may change. Interest and match actions remain local demo interactions.`}</p></div><div class="grid"><section><div class="section-head"><h2>Your daily shortlist <span style="font-size:11px;color:#98a18c;font-weight:400;margin-left:7px">${list.length} ${list.length===1?'role':'roles'}</span></h2><small>${demo?'Practice at your own pace':'Source check · Oct 19, 2026'}</small></div><form id="search-form" class="search">${ico('match')}<input name="query" aria-label="Describe your ideal role" placeholder='Try “product management internships” or “remote part-time”' value="${esc(query)}" maxlength="180"><button aria-label="Find matching roles">${ico('arrow')}</button></form>${query?`<p class="result-note">Showing local matches for “${esc(query)}”. <button class="text-btn" data-action="clear-search">Clear</button></p>`:''}<div class="filters">${[['all','All matches'],['90','90%+ fit'],['remote','Remote'],['intern','Internships'],['full-time','Full-time'],['part-time','Part-time'],['saved','Saved']].map(([v,l])=>`<button class="chip ${filter===v?'selected':''}" data-action="filter:${v}">${filter===v?ico('check'):''}${l}</button>`).join('')}<button class="chip" style="margin-left:auto" data-action="preferences">${ico('settings')} Filters</button></div>${list.length?list.map(jobCard).join(''):`<div class="empty">${ico('briefcase')}<h3>A little room for possibility.</h3><p>No roles match your current filters and preferences. Try a broader search or change your job type and minimum compensation.</p>${btn('Clear search & quick filters','reset-filters')}${btn('Edit preferences','preferences','primary')}</div>`}<p class="welcome-note">Thoughtfully matched. Always your choice.</p></section>${rail()}</div>`}

function scoreFor(j){if(j.demo){let s=j.score;if(j.role!==state.prefs.role)s-=7;if(state.prefs.work!=='Any'&&j.type!==state.prefs.work)s-=5;if(j.industry!==state.prefs.industry)s-=3;if(j.type!=='Remote'&&!j.location.toLowerCase().includes(state.prefs.location.toLowerCase().split(',')[0]))s-=2;s-=Math.min(4,state.dismissed.filter(id=>jobBy(id)?.role===j.role).length*2);return Math.max(40,s)}const a=atsFor(j),same=normalized(j.role)===normalized(state.prefs.role);let score=60*a.matched.length/(a.total||1)+(same?25:0);score+=j.industry===state.prefs.industry?5:0;score+=(state.prefs.work==='Any'||j.type===state.prefs.work)?5:0;score+=(j.type==='Remote'||j.location.toLowerCase().includes(state.prefs.location.toLowerCase().split(',')[0]))?5:0;return Math.max(0,Math.round(score)-Math.min(4,state.dismissed.filter(id=>jobBy(id)?.role===j.role).length*2))}

function applySearch(list,q){q=normalized(q);const rules=[];if(/\bremote\b/.test(q))rules.push(j=>j.type==='Remote');if(/\bhybrid\b/.test(q))rules.push(j=>j.type==='Hybrid');if(/\bintern(?:ship)?s?\b/.test(q))rules.push(j=>j.jobType==='Internship');if(/\bpart time\b/.test(q))rules.push(j=>j.jobType==='Part-time');if(/\bfull time\b/.test(q))rules.push(j=>j.jobType==='Full-time');if(/product market|\bpmm\b/.test(q))rules.push(j=>j.role==='Product Marketing Management');else if(/product manage|\bpm\b/.test(q))rules.push(j=>j.role==='Product Management');if(/\bresearch\b/.test(q))rules.push(j=>/research/i.test(j.title));if(/\bdesign\b/.test(q))rules.push(j=>/design/i.test(j.title));if(/san francisco|bay area/.test(q))rules.push(j=>/San Francisco/.test(j.location));if(/new york|nyc/.test(q))rules.push(j=>/New York/.test(j.location));if(/e commerce/.test(q))rules.push(j=>j.industry==='E-commerce');const companies=jobs.filter(j=>q.includes(normalized(j.company))).map(j=>j.company);if(companies.length)rules.push(j=>companies.includes(j.company));return rules.length?list.filter(j=>rules.every(f=>f(j))):list.filter(j=>normalized(`${j.title} ${j.company} ${(j.keywords||j.skills).join(' ')} ${j.location} ${j.industry}`).includes(q))}

function jobCard(j){const a=atsFor(j);return `<article class="job-card"><div class="job-top"><div class="company-logo ${j.id}">${esc(j.logo)}</div><div class="job-name"><button class="title-button" data-action="job:${j.id}">${esc(j.title)}</button><div class="company">${esc(j.company)} <span style="color:#a7ad9e">· ${esc(j.industry)}</span></div></div><div class="score"><strong>${scoreFor(j)}<span style="font-size:12px">%</span></strong><small>${j.demo?'DEMO MATCH':'FIT PREVIEW'}</small></div></div><div class="job-meta"><span>${ico('pin')}${esc(j.location)}${j.type==='Not specified'?'':' · '+j.type}</span><span>${ico('money')}${esc(j.salary)}</span><span>${ico('clock')}${j.jobType}</span></div><div class="skills">${matchTags(j)}</div><div class="posting-provenance">${sourceMeta(j)}<button class="ats-link" data-action="ats:${j.id}">ATS keyword match · ${a.percent}% ${ico('arrow')}</button></div>${j.noSponsorship?'<p class="eligibility-note">No sponsorship · Check work authorization requirements</p>':''}<div class="job-footer"><div>${j.demo?'<small>Simulated posting</small>':originalLink(j)}</div><div class="actions"><button class="icon-btn" aria-label="${state.saved.includes(j.id)?'Unsave':'Save'} ${esc(j.title)}" data-action="save:${j.id}" style="color:${state.saved.includes(j.id)?'#5c7745':'#9ba391'}">${ico('book')}</button>${jobActions(j)}</div></div></article>`}

function rail(){return `<aside class="rail"><div class="rail-card"><div class="rail-top"><h3>Your match DNA</h3><span class="small-icon">${ico('user')}</span></div><div class="profile-summary"><div class="profile-ring"><div class="avatar">${esc(initials(state.profile.name))}</div></div><h3>${esc(state.profile.name||'Your profile')}</h3><p>${esc(state.profile.headline||'Add your next chapter')}</p><span class="badge" style="margin-top:10px">${state.profile.complete?'✓ Profile ready to match':'Complete your profile'}</span></div><div class="dna-row"><label>YOUR NORTH STAR</label><span>${esc(state.prefs.role)} · Early career</span></div><div class="dna-row"><label>WHERE YOU WANT TO BE</label><span>${ico('pin')} ${esc(state.prefs.location)}</span></div><div class="dna-row"><label>JOB TYPE</label><span>${esc(state.prefs.jobType==='Any'?'Open to all job types':state.prefs.jobType)}</span></div><div class="dna-row"><label>WHAT MATTERS TO YOU</label><span class="chip">${esc(state.prefs.industry)}</span> <span class="chip">${state.prefs.work==='Any'?'Flexible work':esc(state.prefs.work)}</span></div>${btn(`${ico('edit')} Refine preferences`,'preferences')}</div><div class="rail-card insight"><div class="icon-circle">${ico('match')}</div><h3>Clarity, before you apply.</h3><p>Green tags are found in your profile text. Grey tags aren’t found yet. Keyword coverage is a starting point, not an employer decision.</p><button class="text-btn" style="color:#8c7859;margin-top:14px;font-size:10px" data-action="guide">How matching works →</button></div><div class="rail-foot">${ico('lock')}<span>Your interest stays private.<br>Contact unlocks when it’s mutual.</span></div></aside>`}
function showJob(id){const j=jobBy(id),a=atsFor(j);overlay(`${head('A closer look')}<div class="job-top"><div class="company-logo ${j.id}">${esc(j.logo)}</div><div class="job-name"><h2>${esc(j.title)}</h2><div class="company">${esc(j.company)} · ${esc(j.location)}</div></div><div class="score"><strong>${scoreFor(j)}%</strong><small>${j.demo?'DEMO MATCH':'FIT PREVIEW'}</small></div></div><div class="job-meta"><span>${ico('briefcase')}${j.jobType}</span><span>${ico('pin')}${j.type==='Not specified'?'Work arrangement not specified':j.type}</span><span>${ico('money')}${esc(j.salary)}</span></div><div class="posting-provenance">${sourceMeta(j)}</div>${j.url?`<div class="original-callout">${originalLink(j,'Read original posting ↗','btn primary')}<small>${esc(j.ats)}${j.req?' · Req '+esc(j.req):''}<br>Checked ${SOURCE_CHECK_DATE} · ${j.posted}. Availability may change.</small></div>`:''}<div class="match-explain"><strong>Why this made your shortlist</strong><br>${j.demo?'This sample role is used for practicing the match workflow.':`You match ${a.matched.length} of ${a.total} selected posting keywords. Overall fit combines keyword coverage (60%), your target role (25%), and industry, arrangement, and location preferences (15%).`}<br><button class="text-btn" data-action="ats:${id}">Review ATS keyword alignment →</button></div><div class="skills">${matchTags(j)}</div>${j.term?`<h4>TYPE & TIMING</h4><p>${esc(j.term)}</p>`:''}${j.deadline?`<p class="deadline-note">Application deadline: ${new Date(j.deadline+'T12:00:00').toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}</p>`:''}<h4>THE OPPORTUNITY</h4><p>${esc(j.desc)}</p><h4>WHAT YOU’LL DO</h4><ul>${j.duties.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${j.eligibility?`<h4>ELIGIBILITY & DETAILS TO CHECK</h4><p>${esc(j.eligibility)}</p>`:''}${eligibilityError(j)?`<div class="error">${eligibilityError(j)}</div>`:''}<div class="locked">${ico('lock')}Interest is stored only in this prototype. It does not apply to this job or contact the employer.</div><p style="font-size:10px">${j.demo?'Sample posting · not a verified vacancy.':'Employer-source summary. Use the original posting for the full and current terms. ATS alignment is a local keyword estimate, not an employer score.'}</p><div class="panel-footer">${jobActions(j)}</div>`)}

function event(p,text,actor){p.events.push({text,actor,time:new Date().toISOString()})}function pair(id){if(!state.pairs[id])state.pairs[id]={status:'shortlisted',candidate:false,recruiter:false,events:[]};return state.pairs[id]}
function interest(id){if(eligibilityError(jobBy(id))){toast(eligibilityError(jobBy(id)));return}if(!state.profile.complete){startProfile();toast('Complete your profile and work authorization before expressing interest.');return}if(!state.open){toast('Turn on Open to work before expressing interest.');return}let p=pair(id);if(['expired','withdrawn','rejected','offer'].includes(p.status)){if(p.status!=='expired'){toast('This pairing has ended. Explore another opportunity.');return}p=state.pairs[id]={status:'shortlisted',candidate:false,recruiter:false,events:[]}}if(p.candidate)return;p.candidate=true;p.recruiter=p.recruiter||jobBy(id).recruiterInterested;p.status=p.recruiter?'mutual':'interested';event(p,'You expressed private interest','Candidate');if(p.recruiter)event(p,'Both sides expressed interest. Contact details unlocked.','SHORTLIST');save();render();if(p.status==='mutual')showPair(id);else{closeOverlay();toast(jobBy(id).demo?'Interest saved privately in the demo.':'Interest saved locally. No application or employer message was sent.')}}
function statusLabel(s){return ({shortlisted:'Shortlisted',interested:'Interested',invited:'Invited',mutual:'Mutual match',interviewing:'Interviewing',offer:'Offer received',rejected:'Not moving forward',withdrawn:'Withdrawn',expired:'Expired'})[s]||s}
function pairSummary(id,p){const j=jobBy(id);return `<article class="match-card"><div class="job-top"><div class="company-logo ${p.status==='invited'?'':j.id}">${p.status==='invited'?'?':j.logo}</div><div class="job-name"><h3>${j.title}</h3><div class="company">${p.status==='invited'?'Company hidden until mutual interest':j.company} · ${j.location}</div></div><span class="badge ${['expired','withdrawn','rejected'].includes(p.status)?'gray':''}">${statusLabel(p.status)}</span></div><p style="font-size:12px;color:#839075">${p.status==='interested'?'Your interest is saved locally. No application or recruiter message has been sent.':p.status==='invited'?'A simulated recruiter is interested in your profile. Review the sample role and express interest to connect.':activePair(p)?'You both see the potential. Take the next step together.':'This pairing has ended. There are more possibilities on your shortlist.'}</p><div style="display:flex;justify-content:flex-end;margin-top:18px">${btn(activePair(p)?'Open match →':'View activity →',`pair:${id}`,'primary')}</div></article>`}
function activityPage(){let entries=Object.entries(state.pairs);return `${pageTitle('Every step counts.','Your interests, invitations, and next moves in one place.')}<div class="tabs"><button class="active">Pairing activity · ${entries.length}</button><button data-action="dismissed">Passed roles · ${state.dismissed.length}</button></div><div class="full">${entries.length?entries.map(([id,p])=>pairSummary(id,p)).join(''):`<div class="empty">${ico('heart')}<h3>Make your first move.</h3><p>Express interest in a role from your shortlist. Your decision stays private until the feeling is mutual.</p>${btn('Explore my shortlist','nav:shortlist','primary')}</div>`}</div>`}
function matchesPage(){const entries=Object.entries(state.pairs).filter(([id,p])=>activePair(p));return `${pageTitle('When the feeling is mutual.','Real connections start when both sides say yes.')}<div class="banner">${ico('shield')}Contact information is shared only after mutual interest. You control the next step.</div><div class="full">${entries.length?entries.map(([id,p])=>pairSummary(id,p)).join(''):`<div class="empty">${ico('match')}<h3>Your next connection is out there.</h3><p>Switch to the Workflow demo tab and choose the Product Design Intern role at Linear to practice a mutual match.</p>${btn('Find my fit','nav:shortlist','primary')}</div>`}</div>`}
function showPair(id){const j=jobBy(id),p=state.pairs[id];if(!p){showJob(id);return}const unlocked=activePair(p),terminal=['offer','rejected','withdrawn','expired'].includes(p.status);const stages=['shortlisted','interested','mutual','interviewing','offer'];let idx=p.status==='invited'?1:stages.indexOf(p.status);overlay(`${head('Your next chapter')}${!j.demo?'<div class="snapshot-note"><p>Local prototype activity · This interest has not been sent to the employer.</p></div>':''}<span class="badge">${statusLabel(p.status)}</span><h2 style="margin:15px 0 6px">${j.title}</h2><p>${p.status==='invited'?'Company hidden until you express interest':j.company} · ${j.location}</p><div class="progress">${['Shortlisted','Interest','Mutual','Interviewing','Outcome'].map((s,i)=>`<div class="progress-step ${i<=idx?'done':''}">${s}</div>`).join('')}</div>${unlocked?`<div class="contact-box"><h3>${ico('check')} It’s mutual. Let’s connect.</h3><p>${state.mode==='candidate'?'Maya Chen · Talent Partner, '+j.company:esc(state.profile.name)+' · '+esc(state.profile.school)}</p><p>${ico('mail')} ${state.mode==='candidate'?'maya@'+j.company.toLowerCase()+'.example':esc(state.profile.email)}</p><p style="margin-top:5px;font-size:10px">Sample contact details · No messages are sent.</p></div>`:`<div class="locked">${ico('lock')}Contact details are locked. Both sides must express interest.</div>`}${p.status==='offer'?`<div class="offer-box">✦<h3>A new chapter awaits.</h3><p>Offer recorded. Congratulations on your next step!</p></div>`:''}${unlocked&&!terminal?`<h4>MAKE TIME FOR WHAT’S NEXT</h4><p>${p.meeting?'Interview scheduled for '+new Date(p.meeting).toLocaleString('en-US',{dateStyle:'medium',timeStyle:'short'}):'Choose a time to simulate scheduling your first conversation.'}</p>${btn(p.meeting?'Edit interview time':'Schedule a conversation',`schedule:${id}`)}<div class="panel-footer" style="justify-content:flex-start;flex-wrap:wrap">${p.status==='mutual'?btn('Move to interviewing',`transition:${id}:interviewing`,'primary'):btn('Record offer',`transition:${id}:offer`,'primary')+btn('Not moving forward',`transition:${id}:rejected`)}${btn('Withdraw',`withdraw:${id}`,'danger')}</div>`:''}${p.status==='invited'?btn('Express interest & connect',`interest:${id}`,'primary'):''}${p.status==='interested'?`<div class="panel-footer">${btn('Withdraw interest',`withdraw:${id}`,'danger')}</div>`:''}${terminal&&p.status!=='offer'?`<div class="banner">This pairing is ${statusLabel(p.status).toLowerCase()}. ${p.status==='expired'?'You can express interest again after turning visibility on.':'No further transitions are permitted.'}</div>`:''}<h4>THE STORY SO FAR</h4><div class="timeline">${[...p.events].reverse().map(e=>`<div class="event"><strong>${esc(e.text)}</strong><small>${esc(e.actor)} · ${new Date(e.time).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</small></div>`).join('')}</div>`)}
function transition(id,to){const p=state.pairs[id],allowed={mutual:['interviewing','withdrawn'],interviewing:['offer','rejected','withdrawn'],interested:['withdrawn'],invited:['withdrawn']};if(!p||!allowed[p.status]?.includes(to)){toast('This action isn’t available at the current pairing stage.');return}p.status=to;event(p,'Pairing moved to '+statusLabel(to).toLowerCase(),state.mode==='candidate'?'Candidate':'Recruiter');save();render();showPair(id);toast(to==='offer'?'Offer recorded. A new chapter awaits!':'Pairing updated. Your activity timeline is up to date.')}
function schedule(id){const p=state.pairs[id];if(!activePair(p)||p.status==='offer'){toast('Scheduling is available during a mutual match or interview.');return}overlay(`${head('Make room for a conversation')}<p style="font-size:12px;color:#7c8770">Pick an interview time for ${jobBy(id).title}. This simulates a scheduling link; no calendar invite is sent.</p><form id="schedule-form" data-id="${id}" novalidate><div class="field"><label for="meeting">Interview date & time</label><input id="meeting" name="meeting" type="datetime-local" required min="${localDate(new Date(Date.now()+60000))}" value="${p.meeting?localDate(new Date(p.meeting)):''}"><small>Use your local time zone. Choose a time in the future.</small></div><div class="error" id="form-error" role="alert"></div><div class="panel-footer">${btn('Back to match',`pair:${id}`)}<button class="btn primary">Confirm time</button></div></form>`,true)}function localDate(d){return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function guide(){overlay(`${head('A good fit goes both ways.')}<p style="font-size:12px;color:#829173">Three simple steps. A more intentional job search.</p>${[['user','Tell us what makes you, you.','Build your profile with a resume or LinkedIn URL, then set the roles, locations, and industries that matter to you.'],['grid','A shortlist, not a search spiral.','Review ranked roles with clear strengths and gaps. Save a role, pass, or privately express interest.'],['match','Connect when it’s mutual.','Recruiters review de-identified profiles. When both sides are interested, contact details unlock so you can start a conversation.']].map(([i,t,d])=>`<div class="guide-item"><div class="stat-icon">${ico(i)}</div><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}<div class="banner" style="font-size:11px;margin-top:20px">This prototype combines a source-checked job snapshot with mock workflow roles. Search and ATS keyword alignment run locally. ATS feeds, AI, email, verification, and scheduling are not connected.</div><div class="panel-footer">${btn('Sounds like my kind of search','close','primary')}</div>`,true)}
function profilePage(){if(state.mode==='recruiter')return `${pageTitle('Your recruiter profile.','Verified company details and claimed postings.')}<section class="rail-card full"><h2>Maya Chen</h2><p class="subtitle">Talent Partner · Linear</p><div class="review-row"><span>Company email</span><strong>${esc(state.recruiter.email||'Not verified')}</strong></div><div class="review-row"><span>Verified domain</span><strong>${state.recruiter.verified?'linear.app · Demo verification':'Setup required'}</strong></div><div class="review-row"><span>Claimed postings</span><strong>${state.recruiter.claims.length}</strong></div><div class="panel-footer">${btn('Manage company & postings','recruiter-setup','primary')}</div></section>`;let p=state.profile;return `${pageTitle('A little more you.','A thoughtful profile helps the right opportunities find you.')}<section class="rail-card full"><div class="job-top"><div class="avatar">${esc(initials(p.name))}</div><div class="job-name"><h2>${esc(p.name||'Your profile')}</h2><p>${esc(p.headline)}</p></div><span class="badge">${p.complete?'Profile complete':'Setup needed'}</span></div>${[['Email',p.email],['Education',p.school],['Experience',p.experience],['Keyword matching skills',p.skillsText||'Not added'],['Profile source',p.source==='resume'?p.resume:p.linkedin],['Work authorization',state.prefs.auth],['Sponsorship required',state.prefs.sponsor],['Visibility',state.open?'Open to work':'Hidden from recruiter pool']].map(([l,v])=>`<div class="review-row"><span>${l}</span><strong style="overflow-wrap:anywhere">${esc(v||'Not provided')}</strong></div>`).join('')}<div class="panel-footer">${btn('Reset demo','reset-demo')}${btn('Start fresh profile','fresh-profile')}${btn('Edit profile','edit-profile','primary')}</div></section><p class="subtitle">Only your skills, experience, education, and general location are visible before a mutual match.</p>`}
function startProfile(fresh=false){profileDraft=fresh?{name:'',email:'',headline:'',school:'',experience:'0–1 years',source:'linkedin',linkedin:'',resume:'',skillsText:'',terms:false,complete:false}:structuredClone(state.profile);prefsDraft=structuredClone(state.prefs);onboarding=1;profileForm()}
function field(label,name,value,type='text',hint='',required=true){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='text'?'maxlength="160"':''}>${hint?`<small>${hint}</small>`:''}</div>`}
function selectField(label,name,value,options){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`}
function profileForm(){const p=profileDraft,f=prefsDraft;let content='';if(onboarding===1)content=`${field('Your full name','name',p.name)}${field('Email address','email',p.email,'email','Use an address where you would like mutual matches to reach you.')}<label class="check"><input type="checkbox" name="terms" ${p.terms?'checked':''}>I accept the data use terms: use my profile to rank jobs and show a de-identified profile to recruiters when I’m open to work.</label>`;if(onboarding===2)content=`<div class="tabs"><button type="button" class="${p.source==='linkedin'?'active':''}" data-action="source:linkedin">LinkedIn URL</button><button type="button" class="${p.source==='resume'?'active':''}" data-action="source:resume">Upload resume</button></div>${p.source==='linkedin'?field('Your LinkedIn profile URL','linkedin',p.linkedin,'url','Use https://www.linkedin.com/in/your-profile. This demo does not import or fetch your profile.'): `<div class="field"><label for="resume-file">Your resume</label><input id="resume-file" name="resume" type="file" accept=".pdf,.doc,.docx"><small>PDF, DOC, or DOCX · Maximum 5 MB. ${p.resume?'Selected: '+esc(p.resume):''} Files stay on your device; only the filename is saved.</small></div>`}${field('Professional headline','headline',p.headline,'text','For example, “Aspiring product designer”.')}<div class="field"><label for="profile-skills">Skills and experience for keyword matching</label><textarea id="profile-skills" name="skillsText" maxlength="12000">${esc(p.skillsText??'')}</textarea><small>Use your own skill list or resume excerpts. Matching stays in this browser; resume files and LinkedIn profiles are not parsed.</small></div>${field('School or most recent education','school',p.school)}${selectField('Years of experience','experience',p.experience,['0–1 years','1–3 years','3–5 years','5+ years'])}`;if(onboarding===3)content=prefFields(f);if(onboarding===4)content=`<p style="font-size:12px;color:#819074;margin-bottom:10px">Everything look like you? You can go back to edit any step.</p>${[['Name',p.name],['Email',p.email],['Profile source',p.source==='resume'?p.resume:p.linkedin],['Headline',p.headline],['Education',p.school],['Experience',p.experience],['Matching skills',p.skillsText||'Not provided'],['Target role',f.role],['Job type',f.jobType||'Any'],['Location',f.location],['Work arrangement',f.work],['Industry',f.industry],['Minimum pay','$'+f.min+' / hour'],['Authorization',f.auth],['Sponsorship',f.sponsor]].map(([l,v])=>`<div class="review-row"><span>${l}</span><strong style="overflow-wrap:anywhere">${esc(v)}</strong></div>`).join('')}<div class="match-explain">Your profile appears without your name or email until a mutual match. Turning off Open to work removes you from the pool and expires pending pairings.</div><label class="check"><input type="checkbox" name="guide" required>I understand how private interest and mutual matching work.</label>`;overlay(`${head(onboarding===4?'Ready for your next chapter?':'Let’s find your kind of fit.')}<div class="stepbar">${[1,2,3,4].map(i=>`<i class="${i<=onboarding?'active':''}"></i>`).join('')}</div><div class="step-label">Step ${onboarding} of 4 · ${['','Your account','Your story','Your preferences','Review & finish'][onboarding]}</div><form id="profile-form" novalidate>${content}<div id="form-error" class="error" role="alert"></div><div class="panel-footer">${onboarding>1?btn('Back','profile-back'):''}<button class="btn primary">${onboarding===4?'Create my shortlist →':'Continue →'}</button></div></form>`,true)}
function prefFields(f){return `${selectField('Target role','role',f.role,ROLES)}${field('Preferred location','location',f.location,'text','Enter a city or region. Your general location is shown to recruiters.')}<div class="form-row">${selectField('Industry','industry',f.industry,INDUSTRIES)}${selectField('Work arrangement','work',f.work,['Any','Remote','Hybrid','On-site'])}</div>${selectField('Job type','jobType',f.jobType||'Any',JOB_TYPES)}${selectField('Work authorization','auth',f.auth,['Select authorization','Authorized to work in the US','Student / temporary work authorization','Need work authorization'])}${selectField('Sponsorship required','sponsor',f.sponsor,['No','Yes'])}${field('Minimum hourly equivalent (USD)','min',f.min,'number','0–200. Roles with undisclosed or non-USD pay are excluded when a minimum is set. Annual USD salaries use 2,080 hours.')}`}

function preferencesPage(){return `${pageTitle('Give your shortlist direction.','Small preferences. More meaningful possibilities.')}<section class="rail-card full"><form id="preferences-form" novalidate>${prefFields(state.prefs)}<div id="form-error" class="error" role="alert"></div><div class="panel-footer"><button class="btn primary">Save preferences</button></div></form></section>`}
function showPreferences(){overlay(`${head('Find more of your kind.')}<p style="font-size:12px;color:#7b8870">Your preferences refine scores and filter compensation. Skills, role fit, and preferences all contribute.</p><form id="preferences-form" novalidate>${prefFields(state.prefs)}<div id="form-error" class="error" role="alert"></div><div class="panel-footer"><button class="btn primary">Save preferences</button></div></form>`,true)}
function validatePrefs(f){if(!f.location.trim()||f.location.trim().length<2)return 'Enter a preferred city or region with at least 2 characters.';if(f.jobType&&!JOB_TYPES.includes(f.jobType))return 'Choose an available job type.';if(f.auth==='Select authorization')return 'Choose your work authorization so we can recommend eligible roles.';if(f.auth==='Need work authorization'&&f.sponsor!=='Yes')return 'If you need work authorization, select “Yes” for sponsorship required.';if(f.min===''||!Number.isFinite(Number(f.min))||Number(f.min)<0||Number(f.min)>200)return 'Enter a minimum hourly equivalent between $0 and $200.';return ''}
function recruiterPage(){if(!state.recruiter.verified||!state.recruiter.claims.length)return `${pageTitle('Find potential. Build possibility.','Practice hiring with simulated postings and de-identified candidates.')}<section class="hero"><div><div class="eyebrow">A MORE HUMAN WAY TO HIRE</div><h2>Great teams start<br>with a mutual yes.</h2><p>Verify your company, claim an indexed role, and meet a ranked pool of de-identified talent.</p></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="float-card"><b></b><span></span><span></span></div><span class="float-score">✦</span></div></section><section class="rail-card full"><div class="guide-item"><div class="stat-icon">${ico('shield')}</div><div><h3>1. Verify your company email</h3><p>Use your company domain. Verification is simulated in this prototype.</p></div></div><div class="guide-item"><div class="stat-icon">${ico('briefcase')}</div><div><h3>2. Claim an existing posting</h3><p>Claim a role from the mock index instead of posting it again.</p></div></div><div class="guide-item"><div class="stat-icon">${ico('match')}</div><div><h3>3. Invite the people who fit</h3><p>Names and contact details unlock only after mutual interest.</p></div></div><div class="panel-footer">${btn('Set up recruiter workspace →','recruiter-setup','primary')}</div></section>`;const j=jobBy(state.recruiter.claims[0]);const rows=candidateRows();return `${pageTitle('Potential, in good company.','A curated pool of people who could make a difference.',`<span class="badge">${ico('shield')} linear.app · Verified demo</span>`)}<div class="banner">${ico('briefcase')}<div><strong>${j.title}</strong><br><span style="font-size:10px;color:#8b987c">Claimed posting · Linear · San Francisco · ${j.type}</span></div><button class="text-btn" style="margin-left:auto" data-action="manage-claims">Manage postings</button></div><div class="grid"><section><div class="section-head"><h2>Your ranked candidates</h2><small>${Math.max(0,3-state.recruiter.invites.length)} of 3 daily invites left</small></div><div class="locked">${ico('lock')}Names and contact details stay hidden until a mutual match.</div>${rows.length?rows.map(c=>candidateCard(c,j)).join(''):`<div class="empty"><h3>You’re all caught up.</h3><p>All available candidates have been reviewed for this posting.</p></div>`}</section><aside class="rail"><div class="rail-card"><h3>A thoughtful invitation.</h3><p style="margin-top:12px">Invite up to 3 candidates each day. An invitation stays private and shows the role without revealing your company.</p><div class="dna-row"><label>VERIFIED COMPANY</label><span>Linear · linear.app</span></div><div class="dna-row"><label>YOUR COMPANY EMAIL</label><span>${esc(state.recruiter.email)}</span></div><div class="dna-row"><label>POSTINGS CLAIMED</label><span>${state.recruiter.claims.length}</span></div></div><div class="rail-card insight"><div class="icon-circle">${ico('shield')}</div><h3>See skills. See potential.</h3><p>Every profile is de-identified to help you focus on what someone can bring to your team.</p></div></aside></div>`}
function candidateRows(){let r=[{id:'C-1042',score:scoreFor(jobBy(state.recruiter.claims[0]||'linear')),edu:'Public research university · BA, Design',exp:'0–1 years',loc:'San Francisco Bay Area',skills:['Figma','Product thinking','Prototyping'],miss:['Design systems'],self:true},{id:'C-1086',score:94,edu:'Design institute · BFA, Interaction Design',exp:'1–3 years',loc:'Greater New York',skills:['Figma','Design systems','UX research'],miss:['B2B software']},{id:'C-1129',score:89,edu:'Public university · BS, Cognitive Science',exp:'0–1 years',loc:'Greater Los Angeles',skills:['UX research','Prototyping','Collaboration'],miss:['Design systems']}];return r.filter(c=>(!c.self||state.open&&state.profile.complete)&&!state.recruiter.passed.includes(c.id))}
function candidateCard(c,j){const invited=state.recruiter.invites.includes(c.id),p=state.pairs[j.id];return `<article class="job-card candidate-card"><div class="job-top"><div class="company-logo">${ico('user')}</div><div class="job-name"><button class="title-button" data-action="candidate:${c.id}">Candidate ${c.id}</button><div class="company">${c.exp} experience · ${c.loc}</div></div><div class="score"><strong>${c.score}%</strong><small>MATCH</small></div></div><p style="font-size:11px;color:#8c9583;margin:16px 0">${c.edu}</p><div class="skills">${c.skills.map(x=>`<span class="skill">✓ ${x}</span>`).join('')}${c.miss.map(x=>`<span class="skill miss">− ${x}</span>`).join('')}</div><div class="job-footer"><small>Ranked on skills, role fit & preferences</small><div class="actions">${invited?btn(c.self&&activePair(p)?'View mutual match':'Invite sent',c.self&&activePair(p)?`pair:${j.id}`:`candidate:${c.id}`,'primary'):btn('Pass',`pass:${c.id}`)+btn('Invite candidate',`invite:${c.id}`,'primary')}</div></div></article>`}
function showCandidate(id){const c=candidateRows().find(x=>x.id===id);if(!c)return;const j=jobBy(state.recruiter.claims[0]);if(c.self&&activePair(state.pairs[j.id])){showPair(j.id);return}overlay(`${head('Potential, up close')}<span class="badge">DE-IDENTIFIED PROFILE</span><h2 style="margin:20px 0 8px">Candidate ${id}</h2><p>${c.loc} · ${c.exp} experience</p><div class="match-explain"><strong>${c.score}% match for ${j.title}</strong><br>Strong alignment in ${c.skills.join(', ')}. ${c.miss.join(', ')} ${c.miss.length>1?'are':'is'} an area to explore in conversation.</div><h4>EDUCATION</h4><p>${c.edu}</p><h4>EXPERIENCE</h4><p>Early-career designer with project experience in user-centered product design. Collaborated with peers on research, prototypes, and usability testing.</p><h4>MATCHED SKILLS</h4><div class="skills">${c.skills.map(s=>`<span class="skill">✓ ${s}</span>`).join('')}</div><h4>GROWTH AREAS</h4><div class="skills">${c.miss.map(s=>`<span class="skill miss">− ${s}</span>`).join('')}</div><div class="locked">${ico('lock')}Name, email, resume, and identifying links are locked until mutual interest.</div><div class="panel-footer">${state.recruiter.invites.includes(id)?btn('Invite sent','close'):btn('Pass',`pass:${id}`)+btn('Invite candidate',`invite:${id}`,'primary')}</div>`)}
function recruiterSetup(manage=false){recruiterStep=manage?2:1;recruiterDraft=state.recruiter.email;claimDraft=[...state.recruiter.claims];recruiterForm()}
function recruiterForm(){overlay(`${head(recruiterStep===1?'A great team starts here.':'Claim your company’s role.')}<div class="stepbar"><i class="active"></i><i class="${recruiterStep===2?'active':''}"></i></div><div class="step-label">Step ${recruiterStep} of 2 · ${recruiterStep===1?'Verify company':'Claim a posting'}</div><form id="recruiter-form" novalidate>${recruiterStep===1?`<p style="font-size:12px;color:#819074">The demo index contains Linear’s postings. Use a company email ending in <strong>@linear.app</strong> to simulate domain verification.</p>${field('Company email','email',recruiterDraft,'email','For example, maya@linear.app. No email is sent.')}`:`<p style="font-size:12px;color:#819074">Verified domain: linear.app. You can only claim unclaimed postings for your company.</p><label class="claim-option"><input type="checkbox" name="claim" value="linear" ${claimDraft.includes('linear')?'checked':''}><div><strong>Product Design Intern</strong><small>Linear · San Francisco · Hybrid · Indexed today</small></div></label><label class="claim-option" style="opacity:.5;cursor:not-allowed"><input type="checkbox" disabled><div><strong>Associate Product Designer · Notion</strong><small>Different company domain — unavailable to claim</small></div></label>`}<div id="form-error" class="error" role="alert"></div><div class="panel-footer">${recruiterStep===2?btn('Back','recruiter-back'):''}<button class="btn primary">${recruiterStep===1?'Verify company domain →':'Claim posting & view candidates →'}</button></div></form>`,true)}
function invite(id){if(!state.recruiter.verified||!state.recruiter.claims.length){recruiterSetup();return}if(state.recruiter.day!==new Date().toLocaleDateString('en-CA')){state.recruiter.day=new Date().toLocaleDateString('en-CA');state.recruiter.invites=[]}if(state.recruiter.invites.includes(id)){toast('This candidate has already been invited.');return}if(state.recruiter.invites.length>=3){toast('You’ve used all 3 daily invites. Try again tomorrow.');return}if(!candidateRows().find(c=>c.id===id)){toast('This candidate is no longer available. Refresh your candidate list.');return}state.recruiter.invites.push(id);const jid=state.recruiter.claims[0];if(id==='C-1042'){const p=pair(jid);if(['withdrawn','rejected','offer','expired'].includes(p.status)){state.recruiter.invites=state.recruiter.invites.filter(x=>x!==id);toast('This pairing has ended and cannot receive an invitation.');return}p.recruiter=true;p.status=p.candidate?'mutual':'invited';event(p,'A demo recruiter sent a private invitation','Recruiter');if(p.candidate)event(p,'Both sides expressed interest. Contact details unlocked.','SHORTLIST')}save();closeOverlay();render();toast('Invitation saved. Contact stays locked until mutual interest.');if(id==='C-1042'&&activePair(state.pairs[jid]))showPair(jid)}
function error(t){$('#form-error').textContent=t}
function readForm(form){return Object.fromEntries(new FormData(form))}
document.addEventListener('submit',e=>{e.preventDefault();let f=e.target,d=readForm(f);if(f.id==='ats-form'){if(!d.skillsText?.trim()||d.skillsText.trim().length<2){error('Add at least 2 characters describing your skills or experience.');return}state.profile.skillsText=d.skillsText.trim();save();render();atsPanel(f.dataset.id);toast('Your keyword alignment and fit previews have been updated.');return}if(f.id==='search-form'){if(d.query.trim().length<2&&d.query.trim()){toast('Describe your ideal role in at least 2 characters.');return}if(state.searches>=20&&d.query.trim()){toast('Demo search limit reached (20). Use the filter chips or reset the demo.');return}state.searches++;query=d.query.trim();render();return}if(f.id==='profile-form'){if(onboarding===1){Object.assign(profileDraft,{name:d.name?.trim(),email:d.email?.trim(),terms:!!d.terms});if(!profileDraft.name||profileDraft.name.length<2){error('Enter your full name with at least 2 characters.');return}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(profileDraft.email)){error('Enter a valid email address, such as celeste@example.com.');return}if(!d.terms){error('Accept the data use terms to continue with profile matching.');return}}if(onboarding===2){Object.assign(profileDraft,{headline:d.headline?.trim(),school:d.school?.trim(),experience:d.experience,skillsText:d.skillsText?.trim()||''});if(profileDraft.source==='linkedin'){profileDraft.linkedin=d.linkedin?.trim();if(!/^https:\/\/(www\.)?linkedin\.com\/in\/[a-zA-Z0-9_-]+\/?(?:\?.*)?$/.test(profileDraft.linkedin)){error('Use a valid LinkedIn profile URL: https://www.linkedin.com/in/your-profile.');return}}else{const file=f.querySelector('[type=file]').files[0];if(file){if(!/\.(pdf|doc|docx)$/i.test(file.name)||file.size>5*1024*1024){error('Choose a PDF, DOC, or DOCX file smaller than 5 MB.');return}profileDraft.resume=file.name}if(!profileDraft.resume){error('Choose a resume file, or switch to LinkedIn URL.');return}}if(!profileDraft.headline||!profileDraft.school){error('Add your professional headline and school or education to complete your profile.');return}}if(onboarding===3){prefsDraft={...prefsDraft,...d};let err=validatePrefs(prefsDraft);if(err){error(err);return}}if(onboarding===4){if(!d.guide){error('Confirm that you understand private interest and mutual matching.');return}state.profile={...profileDraft,complete:true};state.prefs={...prefsDraft,min:Number(prefsDraft.min)};state.open=true;state.page='shortlist';closeOverlay();render();toast('Your profile is ready. Let’s find your next chapter.');return}onboarding++;profileForm();return}if(f.id==='preferences-form'){let err=validatePrefs(d);if(err){error(err);return}state.prefs={...d,min:Number(d.min)};closeOverlay();render();toast('Preferences saved. Your shortlist scores have been refined.');return}if(f.id==='recruiter-form'){if(recruiterStep===1){recruiterDraft=d.email?.trim().toLowerCase();if(!/^[^\s@]+@linear\.app$/.test(recruiterDraft)){error('Use a valid @linear.app company email. Personal emails and other domains cannot claim Linear postings.');return}recruiterStep=2;recruiterForm()}else{claimDraft=new FormData(f).getAll('claim');if(!claimDraft.includes('linear')){error('Select at least one posting from your verified company before continuing.');return}state.recruiter.verified=true;state.recruiter.email=recruiterDraft;state.recruiter.claims=claimDraft;closeOverlay();render();toast('Company verified in demo. Posting claimed. Your shortlist is ready.')}return}if(f.id==='schedule-form'){const id=f.dataset.id;const date=new Date(d.meeting);if(!d.meeting||isNaN(date)||date<=new Date()){error('Choose a valid date and time in the future.');return}const p=state.pairs[id];if(!['mutual','interviewing'].includes(p.status)){error('This pairing is no longer available for scheduling.');return}p.meeting=date.toISOString();event(p,'Interview time confirmed for '+date.toLocaleString('en-US'),'Candidate');save();render();showPair(id);toast('Interview time saved in this demo.')}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const [action,id,arg]=b.dataset.action.split(':');if(action==='catalog'){state.catalog=id;filter='all';query='';render()}if(action==='sources')sourcesPanel();if(action==='ats')atsPanel(id);if(action==='close')closeOverlay();if(action==='nav'){closeOverlay();state.page=id;render();window.scrollTo(0,0)}if(action==='mode'){closeOverlay();state.mode=id;state.page='shortlist';filter='all';query='';render()}if(action==='guide')guide();if(action==='job')showJob(id);if(action==='pair')showPair(id);if(action==='interest')interest(id);if(action==='save'){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];render();toast(state.saved.includes(id)?'Saved for a closer look.':'Role removed from saved.')}if(action==='dismiss'){state.dismissed.push(id);closeOverlay();render();toast('Role passed. We’ll use this feedback to refine your next shortlist.')}if(action==='filter'){filter=id;render()}if(action==='clear-search'){query='';render()}if(action==='reset-filters'){query='';filter='all';render()}if(action==='visibility'){if(state.open){overlay(`${head('Take a little breathing room?')}<p style="font-size:12px;color:#7d8872">Turning off Open to work hides your profile from recruiters immediately. Pending interests and invitations will expire. Mutual matches and interviews continue.</p><div class="panel-footer">${btn('Keep me visible','close')}${btn('Turn off visibility','hide-confirm','primary')}</div>`,true)}else{if(!state.profile.complete){startProfile();toast('Complete your profile before joining the recruiter pool.')}else{state.open=true;render();toast('You’re visible in the recruiter talent pool.')}}}if(action==='hide-confirm'){state.open=false;Object.values(state.pairs).forEach(p=>{if(['interested','invited','shortlisted'].includes(p.status)){p.status='expired';p.candidate=false;p.recruiter=false;event(p,'Pending pairing expired because candidate visibility was turned off','SHORTLIST')}});closeOverlay();render();toast('Your profile is hidden. Pending pairings have expired.')}if(action==='preferences')showPreferences();if(action==='reset-demo')overlay(`${head('Start with a fresh shortlist?')}<p style="font-size:12px;color:#7d8872">This resets the sample profile, preferences, saved roles, recruiter decisions, and pairing history in this browser.</p><div class="panel-footer">${btn('Keep my progress','close')}${btn('Reset sample data','reset-confirm','primary')}</div>`,true);if(action==='reset-confirm'){state=defaults();filter='all';query='';closeOverlay();render();toast('Demo reset. A fresh chapter awaits.')}if(action==='edit-profile')startProfile();if(action==='fresh-profile')startProfile(true);if(action==='profile-back'){onboarding--;profileForm()}if(action==='source'){const form=$('#profile-form');if(form){const data=readForm(form);['headline','school','experience','linkedin','skillsText'].forEach(k=>{if(data[k])profileDraft[k]=data[k]})}profileDraft.source=id;profileForm()}if(action==='schedule')schedule(id);if(action==='transition')transition(id,arg);if(action==='withdraw'){overlay(`${head('Close this chapter?')}<p style="font-size:12px;color:#7d8872">Withdrawing ends this pairing. You can’t reopen it in this demo. Your other matches will continue.</p><div class="panel-footer">${btn('Keep pairing',`pair:${id}`)}${btn('Withdraw pairing',`transition:${id}:withdrawn`,'danger')}</div>`,true)}if(action==='recruiter-setup')recruiterSetup();if(action==='manage-claims')recruiterSetup(true);if(action==='recruiter-back'){recruiterStep=1;recruiterForm()}if(action==='candidate')showCandidate(id);if(action==='invite')invite(id);if(action==='pass'){state.recruiter.passed.push(id);closeOverlay();render();toast('Candidate passed and removed from this posting’s list.')}if(action==='dismissed')overlay(`${head('Roles you passed on')}<p style="font-size:12px;color:#7d8872;margin-bottom:20px">Your feedback makes tomorrow’s shortlist more you.</p>${state.dismissed.length?state.dismissed.map(id=>{const j=jobBy(id);return `<div class="review-row"><span>${j.company} · ${j.title}</span>${btn('Restore',`restore:${id}`)}</div>`}).join(''):'<p>No passed roles yet.</p>'}`);if(action==='restore'){state.dismissed=state.dismissed.filter(x=>x!==id);closeOverlay();render();toast('Role restored to your shortlist.')}if(action==='notifications'){overlay(`${head('A little update for you')}<div class="guide-item"><div class="stat-icon">${ico('match')}</div><div><h3>Your shortlist is ready.</h3><p>10 source-checked openings are ready to explore. Use the Workflow demo tab and express interest in Linear to practice a mutual match.</p></div></div><p style="font-size:11px;color:#8b9680">Local prototype · No external notifications are sent.</p>`,true)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeOverlay();if(e.key==='Tab'&&$('#overlay').firstChild){const el=[...$('#overlay').querySelectorAll('button,a,input,select,textarea')].filter(n=>!n.disabled);const first=el[0],last=el.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
render();
